import { computed, effect, Injectable, signal } from '@angular/core';
import { TmdbMovie, WatchItem } from './movie';

@Injectable({ providedIn: 'root' })
export class WatchlistStore {
    private readonly KEY = 'watchlist';

    private _items = signal<WatchItem[]>(
        (JSON.parse(localStorage.getItem(this.KEY) ?? '[]') as WatchItem[])
            .map(item => ({ ...item }))
    );

    items = computed(() => {
        const items = this._items();
        const unwatched = items.filter(m => !m.watched);
        const watched = items.filter(m => m.watched);
        return [...unwatched, ...watched];
    });
    count = computed(() => this._items().length);
    watchedCount = computed(() => this._items().filter(m => m.watched).length)

    constructor() {
        effect(() => {
            localStorage.setItem(this.KEY, JSON.stringify(this._items()));
        });
    }

    add(movie: TmdbMovie) {
        const stored = this._items();
        if (stored.some(m => m.id === movie.id)) {
            // still replace with fresh object identities so consumers recompute
            this._items.set(stored.map(m => ({ ...m })));
            return;
        }
        const newItem: WatchItem = {
            id: movie.id,
            title: movie.title,
            poster_path: movie.poster_path,
            release_date: movie.release_date,
            watched: false
        };
        this._items.set([...stored.map(m => ({ ...m })), newItem]);
    }

    remove(id: number) {
        this._items.set(
            this._items()
                .filter(m => m.id !== id)
                .map(m => ({ ...m }))
        );
    }

    toggleWatched(id: number) {
        this._items.set(
            this._items().map(m =>
                ({ ...m, watched: m.id === id ? !m.watched : m.watched })
            )
        );
    }
}

import { TestBed } from '@angular/core/testing';
import { WatchlistStore } from './watchlist-store';

describe('WatchlistStore', () => {
  let service: WatchlistStore;

  beforeEach(() => {
    localStorage.clear();
    TestBed.configureTestingModule({});
    service = TestBed.inject(WatchlistStore);
  });

  it('should be created', () => {
    expect(service).toBeTruthy();
  });

  it('emits a new array from items after toggleWatched', () => {
    service.add({ id: 1, title: 'A', poster_path: null, release_date: '', overview: '' });
    const first = service.items();
    service.toggleWatched(1);
    const second = service.items();
    expect(second).not.toBe(first);
    expect(second[0].watched).toBe(true);
  });

  it('keeps stable insertion order with unwatched first', () => {
    service.add({ id: 1, title: 'A', poster_path: null, release_date: '', overview: '' });
    service.add({ id: 2, title: 'B', poster_path: null, release_date: '', overview: '' });
    service.toggleWatched(1);
    expect(service.items().map(m => m.id)).toEqual([2, 1]);
    service.toggleWatched(2);
    expect(service.items().map(m => m.id)).toEqual([1, 2]);
  });

  it('recomputes after remove', () => {
    service.add({ id: 1, title: 'A', poster_path: null, release_date: '', overview: '' });
    service.add({ id: 2, title: 'B', poster_path: null, release_date: '', overview: '' });
    const before = service.items();
    service.remove(1);
    const after = service.items();
    expect(after).not.toBe(before);
    expect(after.map(m => m.id)).toEqual([2]);
  });
});

